let connection;
function db(){if(!connection)connection=new Promise((resolve,reject)=>{const request=indexedDB.open('paperknow-precheck',1);request.onupgradeneeded=()=>{request.result.createObjectStore('reports',{keyPath:'id'});request.result.createObjectStore('sources',{keyPath:'id'});};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});return connection;}
export async function transact(store,mode,operation){const connection=await db();return new Promise((resolve,reject)=>{const transaction=connection.transaction(store,mode),request=operation(transaction.objectStore(store));let value;request.onsuccess=()=>value=request.result;transaction.oncomplete=()=>resolve(value);transaction.onerror=()=>reject(transaction.error);transaction.onabort=()=>reject(transaction.error||new Error('本地存储失败'));});}
export const repository={all:store=>transact(store,'readonly',s=>s.getAll()),get:(store,id)=>transact(store,'readonly',s=>s.get(id)),save:(store,item)=>transact(store,'readwrite',s=>s.put(item)),remove:(store,id)=>transact(store,'readwrite',s=>s.delete(id))};
// Add missing reports and synchronously commit local records while the transaction is active.
// If the local commit throws, abort the report transaction; callers restore local snapshots.
export async function mergeReportBackup(records,commitLocal){const connection=await db();return new Promise((resolve,reject)=>{const tx=connection.transaction('reports','readwrite'),store=tx.objectStore('reports'),request=store.getAll();let reason;request.onsuccess=()=>{try{const ids=new Set(request.result.map(r=>String(r.id)));for(const row of records)if(!ids.has(String(row.id)))store.add(row);commitLocal(request.result);}catch(error){reason=error;tx.abort();}};tx.oncomplete=()=>resolve();tx.onerror=()=>reject(reason||tx.error||Error('报告合并失败'));tx.onabort=()=>reject(reason||tx.error||Error('报告合并取消'));});}
